import{_ as o,o as t,c as d,a1 as c}from"./chunks/framework.BKrM4vFX.js";const k=JSON.parse('{"title":"taxcom-mock — эмулятор Такском API v2","description":"taxcom-mock — read-only эмулятор Такском API v2 для чтения данных ОФД. Документация авторизации, запросов, документов и запуска.","frontmatter":{"sourcePath":"services/taxcom-mock/README.md"},"headers":[{"level":1,"title":"taxcom-mock — Такском, read-only кабинет/ОФД (API v2)","slug":"taxcom-mock-Такском-read-only-кабинетОФД-api-v2","link":"#taxcom-mock-Такском-read-only-кабинетОФД-api-v2","children":[{"level":2,"title":"Запуск","slug":"Запуск","link":"#Запуск","children":[]},{"level":2,"title":"Контракт","slug":"Контракт","link":"#Контракт","children":[]},{"level":2,"title":"Env","slug":"env","link":"#env","children":[]},{"level":2,"title":"Сценарии и ограничения","slug":"Сценарии-и-ограничения","link":"#Сценарии-и-ограничения","children":[]},{"level":2,"title":"Байтовые квоты состояния (PD-02)","slug":"Байтовые-квоты-состояния-pd-02","link":"#Байтовые-квоты-состояния-pd-02","children":[]}]}],"relativePath":"services/taxcom-mock/README.md","filePath":"services/taxcom-mock/README.md"}'),s={name:"services/taxcom-mock/README.md"};function a(i,e,r,n,l,h){return t(),d("div",null,[...e[0]||(e[0]=[c(`<p>© 2026 ООО «Аксиома» ИНН:7842223709 · mock-services · Apache-2.0 SPDX-License-Identifier: Apache-2.0</p><h1 id="taxcom-mock-Такском-read-only-кабинетОФД-api-v2" tabindex="-1">taxcom-mock — Такском, read-only кабинет/ОФД (API v2) <a class="header-anchor" href="#taxcom-mock-Такском-read-only-кабинетОФД-api-v2" aria-label="Permalink to &quot;taxcom-mock — Такском, read-only кабинет/ОФД (API v2)&quot;">​</a></h1><p>Десятый сервис стенда, касса/ОФД №5, issue #112. <strong>Только чтение</strong> документов, уже принятых ОФД: это не очередь печати, не Ferma, не АТОЛ и не OKassa. Node ≥18, CommonJS, zero dependencies, общее ядро <code>packages/core</code> не изменено.</p><p>Источник (2026-10-11, API Help v2.17): официальная документация Такском (авторизация/discovery, документы, частота опроса и границы интеграции). <a href="./../../docs/integration/taxcom">Рецепт интеграции, curl, сценарии и полный список <code>[VERIFY]</code>/<code>[FORK]</code></a>, <a href="https://github.com/rucorp/mock-services/blob/main/docs/openapi/taxcom-mock.openapi.json" target="_blank" rel="noreferrer">OpenAPI</a>, <a href="https://github.com/rucorp/mock-services/blob/main/protocols/taxcom-ofd.json" target="_blank" rel="noreferrer">drift-манифест</a>.</p><h2 id="Запуск" tabindex="-1">Запуск <a class="header-anchor" href="#Запуск" aria-label="Permalink to &quot;Запуск&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> start:taxcom</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">        # :3109</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test:taxcom</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">         # HTTP selftest на :0, без Docker</span></span></code></pre></div><p>Публичных тестовых <code>login</code>/<code>password</code>/<code>Integrator-ID</code> Такском не публикует — их выдаёт техподдержка/кабинет. В моке работают <strong>синтетические</strong> дефолты <code>taxcommocktest</code> / <code>mockpass123</code> / <code>TAXCOMMOCKTEST</code>: они печатаются в стартовом логе и не являются реквизитами провайдера. Заданные через env креды в логе скрываются; production-реквизиты в код и compose не попадают. В owned-песочнице креды генерируются при <code>POST /sandboxes</code>.</p><p>Docker: сервис есть в корневом <code>docker-compose.yml</code> (bind <code>127.0.0.1:3109</code> по умолчанию) и в <code>docker-compose.include.yml</code> (профиль <code>mock</code>). Для include с локальной сборкой:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -t</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mock-services:taxcom-local</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">MOCK_IMAGE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">mock-services</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> MOCK_IMAGE_TAG</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">taxcom-local</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> MOCK_IMAGE_DIGEST</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;&#39;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docker-compose.include.yml</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --profile</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mock</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> up</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> taxcom-mock</span></span></code></pre></div><p>Закреплённый GHCR-релиз новый сервис ещё не содержит: образ и pin публикует владелец отдельно.</p><h2 id="Контракт" tabindex="-1">Контракт <a class="header-anchor" href="#Контракт" aria-label="Permalink to &quot;Контракт&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Метод</th><th>Назначение</th></tr></thead><tbody><tr><td><code>POST /API/v2/Login</code></td><td>заголовок <code>Integrator-ID</code> + JSON-тело → <code>{token}</code> (временный marker)</td></tr><tr><td><code>GET /API/v2/AccountList</code></td><td>договоры/личные кабинеты и права пользователя</td></tr><tr><td><code>GET /API/v2/NewDocuments?an=&amp;id=</code></td><td>поток новых ФД: 10 суток, ≤ 10 000 за вызов, курсор по <code>id</code></td></tr><tr><td><code>GET /health</code>, <code>GET /openapi.json</code></td><td>healthcheck, OpenAPI 3.1</td></tr><tr><td><code>GET /admin</code>, <code>GET /admin/journal</code></td><td>read-only консоль, журнал без секретов</td></tr><tr><td><code>/mock/time</code>, <code>/mock/state</code>, <code>/mock/reset</code>, <code>/mock/scenarios</code></td><td>часы, fixtures, reset, сценарии</td></tr><tr><td><code>/sandboxes</code>, <code>/sandboxes/me</code>, <code>/sandboxes/me/reset</code>, <code>/sandboxes/me/reset-creds</code>, <code>/mock/sandboxes</code></td><td>стандартный sandbox control plane</td></tr></tbody></table><p><code>POST /API/v2/Login</code> требует заголовок <code>Integrator-ID</code> и JSON-тело. <strong>[VERIFY]</strong> Официальная схема <code>Login_Request</code> в публичной HTML-части API Help не раскрыта, поэтому реализована консервативная форма <code>{login, password}</code>: оба поля обязательны, неизвестные ключи → <code>400</code> с пометкой <code>verify: &quot;Login_Request [VERIFY]&quot;</code>. Имя поля ответа (<code>token</code>) — тоже <strong>[VERIFY]</strong>.</p><p>Все методы чтения требуют заголовок <code>Session-Token</code>. TTL маркера — <strong>300 с (5 минут)</strong>, sliding от последнего использования, на <strong>виртуальных часах</strong>; просроченный → <code>401</code>. <strong>[FORK]</strong> Повторный Login выдаёт новый маркер, прежний живёт до своего TTL (срез формулирует иначе — см. гайд и манифест).</p><p><code>NewDocuments</code> возвращает документы за последние <strong>10 суток</strong> (нижняя граница включена), не более <strong>10 000</strong> за вызов, с сортировкой по времени приёма <code>receivedAt</code> (не по фискальному <code>dateTime</code>). Первый вызов — без <code>id</code>; далее передаётся <code>id</code> последнего полученного документа; пустой массив — хвост. Ошибки среза: <strong>3106</strong> (нет доступной ККТ → HTTP 403) и <strong>2203</strong> (некорректный курсор → HTTP 400); соответствие HTTP-статусам — <strong>[VERIFY]</strong>. Конверт ошибки <code>{errorCodeId, message, field, hint, doc}</code>, для прочих случаев <code>errorCodeId</code> равен статусу. Рекомендация опрашивать «не чаще раза в минуту» — совет документации, не правило мока.</p><p>Типы: <code>openShift</code>, <code>closeShift</code>, <code>currentStateReport</code>, <code>receipt</code>, <code>receiptCorrection</code>, <code>bso</code>, <code>bsoCorrection</code>. Демо-каталог каждой песочницы: договор <code>1000001</code> (ККТ с доступом и без согласия), <code>1000002</code> (нет доступной ККТ → 3106), <code>1000003</code> (нет согласия, скрыт из <code>AccountList</code>); 12 документов в окне 10 суток, включая возврат прихода (<code>operationType=2</code>) и документ старше окна (в выдачу не попадает). Суммы — <strong>в целых копейках</strong> (конвенция ФФД, <strong>[FORK]</strong>). Демо-документы задаются смещением от базы стенда (<code>MOCK_VIRTUAL_CLOCK</code> либо wall-clock), чтобы окно не устаревало <strong>[FORK]</strong>.</p><h2 id="env" tabindex="-1">Env <a class="header-anchor" href="#env" aria-label="Permalink to &quot;Env&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Переменная</th><th>Дефолт / назначение</th></tr></thead><tbody><tr><td><code>MOCK_HOST</code>, <code>MOCK_PORT</code></td><td><code>0.0.0.0</code>, <code>3109</code>; bind/порт сервера</td></tr><tr><td><code>MOCK_HEALTH_PATH</code></td><td><code>/health</code> в compose; используется Docker healthcheck, маршрут сервиса фиксирован</td></tr><tr><td><code>MOCK_TAXCOM_LOGIN</code></td><td><code>taxcommocktest</code>; синтетический логин default-песочницы</td></tr><tr><td><code>MOCK_TAXCOM_PASSWORD</code></td><td><code>mockpass123</code>; синтетический пароль, не выводится в лог при override</td></tr><tr><td><code>MOCK_TAXCOM_INTEGRATOR_ID</code></td><td><code>TAXCOMMOCKTEST</code>; синтетический ID интегратора для заголовка <code>Integrator-ID</code></td></tr><tr><td><code>MOCK_TAXCOM_SESSION_TTL_SECS</code></td><td><code>300</code>; целые секунды 1..31536000 на виртуальных часах, <code>0</code> запрещён</td></tr><tr><td><code>MOCK_TAXCOM_PUBLIC_BASE_URL</code></td><td><code>http://localhost:\${MOCK_TAXCOM_HOST_PORT:-3109}</code>; публичная база provisioning-ссылок</td></tr><tr><td><code>MOCK_VIRTUAL_CLOCK</code></td><td>пусто → текущее время; ISO/длительность начальных виртуальных часов</td></tr><tr><td><code>MOCK_HOSTED</code></td><td><code>false</code>; hosted fail-closed для control endpoints</td></tr><tr><td><code>MOCK_TENANCY</code></td><td><code>namespaces</code>, при hosted → <code>owned</code>; поддерживается <code>off</code></td></tr><tr><td><code>MOCK_ADMIN_TOKEN</code></td><td>пусто; защита <code>/admin*</code>, также operator access</td></tr><tr><td><code>MOCK_OPERATOR_TOKEN</code></td><td>пусто; защита <code>/mock/*</code></td></tr><tr><td><code>MOCK_SANDBOX_TOKEN</code></td><td>пусто; owner-token default-песочницы; при <code>MOCK_HOSTED=1</code> без него <code>default</code> не обслуживается (MS-12)</td></tr><tr><td><code>MOCK_SANDBOX_TTL_MS</code></td><td>owned: <code>86400000</code>, иначе <code>0</code>; wall-clock TTL песочницы</td></tr><tr><td><code>MOCK_SANDBOX_MAX</code></td><td><code>100</code>; максимум именованных песочниц</td></tr><tr><td><code>MOCK_SANDBOX_MAX_DOCUMENTS</code></td><td>owned: <code>5000</code>, иначе <code>0</code>; число ФД + живых сессий (квота ядра)</td></tr><tr><td><code>MOCK_SANDBOX_HOST_SUFFIX</code></td><td>пусто; host-selector ядра для песочниц</td></tr><tr><td><code>MOCK_SANDBOX_CREATE_LIMIT</code></td><td><code>20</code>; создание owned-песочниц с IP за час, <code>0</code> без лимита</td></tr><tr><td><code>MOCK_SANDBOX_SWEEP_MS</code></td><td><code>60000</code>; интервал wall-clock sweep, unref timer</td></tr><tr><td><code>MOCK_STATE_FILE</code></td><td>пусто; persist default state, compose <code>/data/taxcom-state.json</code></td></tr><tr><td><code>MOCK_SANDBOX_FILE</code></td><td>по ядру из state path; compose <code>/data/taxcom-sandboxes.json</code></td></tr><tr><td><code>MOCK_TAXCOM_BIND_IP</code>, <code>MOCK_TAXCOM_HOST_PORT</code></td><td>compose-only: <code>127.0.0.1</code>, <code>3109</code></td></tr><tr><td><code>MOCK_TAXCOM_CADDY_DOMAIN</code></td><td>include-only: пусто; optional reverse proxy label</td></tr></tbody></table><p>В owned-запросах добавляйте <code>X-Mock-Sandbox</code> + <code>X-Sandbox-Token</code> <strong>наряду с</strong><code>Integrator-ID</code> (на Login) и <code>Session-Token</code> (на чтение). Чужие токены и знание ID прав не дают. Control token в hosted обязателен; оператор управляет песочницами, владелец — только своей. Reset/state import/ротация отзывают маркеры; экспорт <code>/mock/state</code> их не раскрывает, <code>/sandboxes/me</code> не раскрывает креды повторно. Persist files содержат mock-маркеры/креды: защищайте volume и не храните реальные ФД и ПДн. <a href="./../../SECURITY">Модель угроз</a>.</p><h2 id="Сценарии-и-ограничения" tabindex="-1">Сценарии и ограничения <a class="header-anchor" href="#Сценарии-и-ограничения" aria-label="Permalink to &quot;Сценарии и ограничения&quot;">​</a></h2><p><code>X-Mock-Scenario: fail|hang|duplicate|latency:200ms|http-500|http-504</code>. В <code>POST /mock/scenarios</code> доступны <code>target: auth|read|*</code>, <code>times</code>, <code>persistent</code>, <code>match</code>; сценарии и журнал изолированы по песочницам. <code>duplicate</code> повторяет первый документ (тот же <code>id</code>/ФД/ФП) до курсорной нарезки, лимит 10 000 сохраняется. Виртуальное время двигается <code>POST /mock/time</code>.</p><p><strong>Не моделируется:</strong> создание/фискализация чека, возврат, callback печати, очередь статусов, чтение одного ФД по ID (публичный URL не подтверждён), статистика, агрегаты смены со ставками НДС 22%/22-122 (имена полей срезом не раскрыты — <strong>[VERIFY]</strong>). Известный маршрут с другим методом → <code>405</code>, неизвестный <code>/API/...</code> → <code>404</code>, обе с подсказкой. У сервиса нет ни callback, ни webhook — исходящих HTTP-запросов нет, поэтому очередь доставки ядра и SSRF-политика к этому адаптеру не подключаются. Локальные решения — <code>[VERIFY]</code>/<code>[FORK]</code> в гайде и манифесте, а не гарантия соответствия стенду провайдера.</p><h2 id="Байтовые-квоты-состояния-pd-02" tabindex="-1">Байтовые квоты состояния (PD-02) <a class="header-anchor" href="#Байтовые-квоты-состояния-pd-02" aria-label="Permalink to &quot;Байтовые квоты состояния (PD-02)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Env</th><th>Дефолт</th><th>Назначение</th></tr></thead><tbody><tr><td><code>MOCK_SANDBOX_MAX_STATE_BYTES</code></td><td>пусто: <code>8388608</code> (8 МиБ) при <code>maxDocuments &gt; 0</code>, иначе без лимита</td><td>байты JSON одной песочницы; <code>0</code> выключает</td></tr><tr><td><code>MOCK_SANDBOX_GLOBAL_MAX_STATE_BYTES</code></td><td><code>67108864</code> (64 МиБ)</td><td>сумма байт JSON всех песочниц рантайма, включая <code>default</code>; <code>0</code> выключает</td></tr></tbody></table><p>Значения задаются в целых байтах. Пусто сохраняет дефолты. Квота per-sandbox не ограничивает память контейнера; общий бюджет меньше <code>mem_limit: 128m</code>, но не равен RSS. Превышение глобального бюджета на записи или байтовых квот при импорте <code>/mock/state</code> → HTTP 400, <code>errorCode: 400</code>, <code>kind: &#39;bytes&#39;</code>, <code>code: sandbox_state_budget_exceeded</code> / <code>sandbox_state_quota_exceeded</code>, с откатом отклонённого состояния. Правила/история/журнал остаются volatile. Подробности — <a href="./../../packages/core/README#байтовые-квоты-песочниц-pd-02-74">документация ядра</a>.</p>`,26)])])}const _=o(s,[["render",a]]);export{k as __pageData,_ as default};
